/**
 * Configuration class for Hypertube runtime initialization.
 * Handles loading configuration from environment variables, files, and default values.
 * Works in both Node.js and browser environments.
 */
export class GraftConfig {
  /** @type {string} */
  static graftName: string;
  /** @type {string} */
  static graftConfigEnvVar: string;
  /** @type {string} */
  static runtimeName: string;
  /** @type {string} */
  static module: string;
  /** @type {string} */
  static host: string;
  /** @type {boolean} */
  static stateless: boolean;
  /** @type {RuntimeContext} */
  static rtmCtx: RuntimeContext;
  /** @type {Record<string, string | string[]>} */
  static headers: Record<string, string | string[]>;
  /**
   * Checks if the code is running in a Node.js environment.
   * @private
   * @returns {boolean} True if running in Node.js, false otherwise
   */
  private static #isNodeEnvironment;
  /**
   * @private
   * @param {string} moduleId
   * @returns {any}
   */
  private static #nodeRequire;
  /**
   * Lazily initializes Node.js require helper and package directory for hosted module resolution.
   * @private
   */
  private static #ensureNodeBootstrap;
  /**
   * @private
   * @param {string} candidate
   * @returns {boolean}
   */
  private static #pathExists;
  /**
   * @private
   * @param {string} packageDir
   * @param {string} moduleRoot
   */
  private static #copyResourcesToModuleRoot;
  /**
   * @private
   * @param {string} packageDir
   * @param {string} moduleToken
   * @returns {string}
   */
  private static #joinPackageModulePath;
  /**
   * Resolves the hosted module folder inside the installed @graft package.
   * @private
   * @param {string} packageDir
   * @param {string} moduleToken
   * @returns {string}
   */
  private static #resolveHostedModulePath;
  /**
   * @private
   * @returns {string}
   */
  private static #resolvePackageModulePath;
  /**
   * Adds configuration to Hypertube with the specified priority.
   * @private
   * @param {ConfigPriority} priority - The priority level for the configuration
   * @param {string} config - The configuration string to add
   */
  private static #addConfigToHypertube;
  /**
   * @private
   * @param {string} p
   * @returns {string}
   */
  private static #resolveConfigPath;
  /**
   * @private
   * @param {ConfigPriority} priority
   * @param {string} priorityName
   * @param {string} varName
   */
  private static #tryAddFromEnv;
  /**
   * @private
   * @param {ConfigPriority} priority
   * @param {string} priorityName
   * @param {string} fileNameOrPath
   */
  private static #tryAddFromFile;
  /**
   * @private
   * @param {string} connectionString
   */
  private static #registerDefaultLibrary;
  /**
   * Sets user configuration with User priority.
   * @param {string} config - The configuration string to set
   */
  static setConfig(config: string): void;
  /**
   * Sets default headers for the current runtime connection.
   * @param {Record<string, string | string[]>} headers
   */
  static setHeaders(headers: Record<string, string | string[]>): void;
  /**
   * Invokes an async function with temporary thread-local headers.
   * @param {() => Promise<any>} func
   * @param {Record<string, string | string []>} headers
   * @returns {Promise<any>}
   */
  static invokeWithHeaders(
    func: () => Promise<any>,
    headers: Record<string, string | string[]>,
  ): Promise<any>;
  /** @type {string|null} */
  static #runtimeConfigEnvVarOverride: string | null;
  /**
   * Overrides the runtime-specific configuration environment variable name.
   * Must be called before the first {@link GraftConfig.init}.
   * @param {string} envVarName
   */
  static setRuntimeConfigEnvVar(envVarName: string): void;
  static #resolveRuntimeConfigEnvVar(): string;
  /**
   * Initializes the runtime context and loads configurations in priority order.
   */
  static init(): void;
}
